local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
-- Like i3 resize mode: Mod+R, then arrows or hjkl resize; Escape, Return or Mod+R leave
hl.bind(mainMod .. " + R", hl.dsp.submap("resize"))
hl.define_submap("resize", function()
    for _, k in ipairs({ { "left", "H", -20, 0 }, { "right", "L", 20, 0 }, { "up", "K", 0, -20 }, { "down", "J", 0, 20 } }) do
        for i = 1, 2 do
            hl.bind(k[i], hl.dsp.window.resize({ x = k[3], y = k[4], relative = true }), { repeating = true })
        end
    end
    for _, key in ipairs({ "escape", "Return", mainMod .. " + R" }) do
        hl.bind(key, hl.dsp.submap("reset"))
    end
end)
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu))  -- like Spotlight
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("pidof hyprlock || hyprlock"))
-- Tiled windows on a workspace in screen order (left to right, then top to bottom)
local function in_screen_order(workspace, keep)
    local wins = {}
    for _, w in ipairs(hl.get_workspace_windows(workspace)) do
        if not w.floating and keep(w) then table.insert(wins, w) end
    end
    table.sort(wins, function(a, b)
        if a.at.x ~= b.at.x then return a.at.x < b.at.x end
        return a.at.y < b.at.y
    end)
    return wins
end
-- Like i3 layout tabbed: tab every tiled window on the workspace, in screen order
local function tab_workspace()
    local active = hl.get_active_window()
    if not active or active.group then return end
    local wins = in_screen_order(active.workspace, function(w) return not w.group end)
    hl.dispatch(hl.dsp.focus({ window = wins[1] }))
    hl.dispatch(hl.dsp.group.toggle())
    local group = hl.get_active_window().group
    if not group then return end
    for i = 2, #wins do group:add(wins[i]) end
    hl.dispatch(hl.dsp.focus({ window = active })) -- keep the window you were on as the visible tab
end
-- The tab bar fills the top gap instead of adding to it, so tabbing doesn't push the window down
local tabbed_gaps = hl.workspace_rule({ workspace = "w[g1]", gaps_out = { top = 0, right = 20, bottom = 20, left = 20 } })
-- Untab back into screen order matching the tab order
local function untab_group(active)
    local order, member = {}, {}
    for _, w in ipairs(active.group.members) do
        table.insert(order, w)
        member[w.address] = true
    end
    -- Hyprland lays out the ungrouped windows before it notices the group is gone, so switch
    -- the tabbed gap off first or the windows jump up to the top and back down
    tabbed_gaps:set_enabled(false)
    hl.dispatch(hl.dsp.group.toggle())
    -- where ungrouped windows land depends on focus and the cursor, so swap them into tab order
    for i, want in ipairs(order) do
        local now = in_screen_order(active.workspace, function(w) return member[w.address] end)[i]
        if now and now.address ~= want.address then
            hl.dispatch(hl.dsp.focus({ window = want }))
            hl.dispatch(hl.dsp.window.swap({ target = "address:" .. now.address }))
        end
    end
    tabbed_gaps:set_enabled(true)
    hl.dispatch(hl.dsp.focus({ window = active }))
end
hl.bind(mainMod .. " + W", tab_workspace)
-- Like i3 layout toggle split: untab the group, otherwise flip the split
hl.bind(mainMod .. " + E", function()
    local active = hl.get_active_window()
    if not active then return end
    if active.group then untab_group(active) else hl.dispatch(hl.dsp.layout("togglesplit")) end
end)
hl.config({ binds = { movefocus_cycles_groupfirst = true } })  -- focus keys walk tabs first
hl.config({ group = {
    col = { border_active = "rgba(d65d0e99)", border_inactive = "rgba(50494566)" },  -- same as ungrouped windows
    -- macOS-style tabs: filled rounded pills, the active one lighter with a bolder title, no underline
    groupbar = {
        font_family = "Adwaita Sans", font_size = 11, height = 18,  -- 18 + gaps_out 2 = general gaps_out 20, see the w[g1] rule
        font_weight_active = "semibold", font_weight_inactive = "normal",
        gradients = true, indicator_height = 0,
        gradient_rounding = 8, gradient_round_only_edges = false,
        gaps_in = 4, gaps_out = 2, keep_upper_gap = false,  -- tabs sit right on top of the window
        text_color          = light and "rgba(323236ff)" or "rgba(ebdbb2ff)",
        text_color_inactive = light and "rgba(77767bff)" or "rgba(a89984ff)",
        col = {
            active   = light and "rgba(fafafaff)" or "rgba(504945ff)",
            inactive = light and "rgba(d8d7d4ff)" or "rgba(3c3836ff)",
        },
    },
} })
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))  -- like i3 $mod+f

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Move focus with mainMod + vim keys
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))

-- Move active window within the workspace with mainMod + SHIFT + arrow keys / vim keys
for key, dir in pairs({ left = "left", right = "right", up = "up", down = "down", H = "left", L = "right", K = "up", J = "down" }) do
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ direction = dir, group_aware = true }))  -- enters/leaves tab groups like i3
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

